@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg-dark: #0A1320;
  --bg-card: #0D1B2A;
  --bg-surface: #1B2838;
  --bg-surface-light: #2C3E50;
  --primary: #0077B6;
  --primary-light: #00B4D8;
  --accent-green: #6CC24A;
  --text-main: #FFFFFF;
  --text-muted: #A9B4C2;
  --border-color: rgba(255, 255, 255, 0.1);
  --nav-bg: rgba(10, 19, 32, 0.85);

  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 2rem;
  --spacing-xl: 4rem;
  --spacing-2xl: 6rem;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--bg-dark);
  color: var(--text-main);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: var(--primary-light);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--primary);
}

ul {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4 {
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
}

h1 { font-size: 3.5rem; letter-spacing: -1px; }
h2 { font-size: 2.5rem; letter-spacing: -0.5px; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }
p { margin-bottom: var(--spacing-md); color: var(--text-muted); }

.text-gradient {
  background: linear-gradient(90deg, var(--primary-light), var(--accent-green));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.section {
  padding: var(--spacing-2xl) 0;
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
.grid-3 { grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: 4px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  border: none;
  font-size: 1rem;
  gap: 0.5rem;
}

.btn-primary {
  background-color: var(--primary);
  color: white;
  box-shadow: 0 4px 14px rgba(0, 119, 182, 0.4);
}

.btn-primary:hover {
  background-color: var(--primary-light);
  color: #000;
  transform: translateY(-2px);
}

.btn-secondary {
  background-color: transparent;
  color: white;
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  background-color: var(--bg-surface);
  border-color: var(--primary-light);
}

/* Header & Nav */
header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  background: var(--nav-bg);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid var(--border-color);
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: white;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo i { color: var(--accent-green); }

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--spacing-lg);
}

.nav-item {
  position: relative;
  font-weight: 500;
  color: var(--text-main);
  cursor: pointer;
  padding: 0.5rem 0;
}

.nav-item:hover, .nav-item.active {
  color: var(--primary-light);
}

/* Dropdown */
.dropdown {
  position: relative;
}

.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all 0.2s ease;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.dropdown:hover .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.dropdown-item {
  display: block;
  padding: 0.75rem 1rem;
  color: var(--text-main);
  border-bottom: 1px solid var(--border-color);
}

.dropdown-item:last-child { border-bottom: none; }
.dropdown-item:hover { background-color: var(--bg-surface-light); color: var(--primary-light); }

/* Hero Section */
.hero {
  padding: calc(80px + var(--spacing-2xl)) 0 var(--spacing-2xl);
  text-align: center;
  background: radial-gradient(circle at top center, var(--bg-card) 0%, var(--bg-dark) 100%);
  position: relative;
  overflow: hidden;
}

.hero::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: url('data:image/svg+xml;utf8,<svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg"><circle cx="20" cy="20" r="1" fill="rgba(255,255,255,0.05)"/></svg>');
  z-index: 0;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  margin: 0 auto;
}

.hero-actions {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  margin-top: var(--spacing-lg);
}

/* Cards */
.card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  border-color: var(--primary-light);
}

.card-icon {
  font-size: 2.5rem;
  color: var(--primary-light);
  margin-bottom: var(--spacing-md);
  display: inline-block;
}

/* Tabs */
.tabs-container {
  margin-top: var(--spacing-lg);
}

.tabs-nav {
  display: flex;
  overflow-x: auto;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: var(--spacing-lg);
  scrollbar-width: none;
}

.tabs-nav::-webkit-scrollbar { display: none; }

.tab-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  padding: 1rem 1.5rem;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  position: relative;
  white-space: nowrap;
}

.tab-btn.active {
  color: var(--text-main);
}

.tab-btn.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: var(--primary-light);
}

.tab-pane {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-pane.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Accordion */
.accordion {
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
}

.accordion-item {
  border-bottom: 1px solid var(--border-color);
}

.accordion-item:last-child {
  border-bottom: none;
}

.accordion-header {
  width: 100%;
  text-align: left;
  background: var(--bg-card);
  padding: 1.5rem;
  border: none;
  color: var(--text-main);
  font-size: 1.25rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background 0.3s;
}

.accordion-header:hover {
  background: var(--bg-surface);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  background: var(--bg-surface);
  padding: 0 1.5rem;
}

.accordion-item.active .accordion-content {
  padding: 1.5rem;
  max-height: 500px;
}

.accordion-icon {
  transition: transform 0.3s ease;
}

.accordion-item.active .accordion-icon {
  transform: rotate(180deg);
}

/* Diagrams */
.diagram-container {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: var(--spacing-xl);
  display: flex;
  justify-content: center;
  align-items: center;
  margin-top: var(--spacing-lg);
}

.diagram {
  display: flex;
  gap: 2rem;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
}

.diagram-node {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: 1.5rem;
  border-radius: 50%;
  width: 200px;
  height: 200px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  box-shadow: 0 10px 20px rgba(0,0,0,0.3);
  position: relative;
  z-index: 2;
}

.diagram-node i {
  font-size: 2rem;
  color: var(--primary-light);
  margin-bottom: 0.5rem;
}

.diagram-connector {
  flex-grow: 1;
  height: 2px;
  background: linear-gradient(90deg, var(--primary-light), var(--accent-green));
  position: relative;
  min-width: 50px;
  z-index: 1;
}

/* Stats */
.stats-container {
  display: flex;
  justify-content: center;
  gap: 4rem;
  flex-wrap: wrap;
}

.stat-circle {
  width: 220px;
  height: 220px;
  border-radius: 50%;
  border: 4px solid var(--bg-surface);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  position: relative;
  background: var(--bg-card);
  box-shadow: 0 0 30px rgba(0, 180, 216, 0.1);
}

.stat-circle::before {
  content: '';
  position: absolute;
  top: -4px; left: -4px; right: -4px; bottom: -4px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: var(--primary-light);
  border-right-color: var(--accent-green);
  transform: rotate(45deg);
}

.stat-number {
  font-size: 3rem;
  font-weight: 700;
  color: white;
  line-height: 1;
  margin-bottom: 0.5rem;
}

.stat-label {
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 0 1rem;
}

/* Timeline */
.timeline {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  max-width: 800px;
  margin: 0 auto;
}

.timeline-item {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.timeline-time {
  font-weight: 700;
  color: var(--primary-light);
  width: 120px;
  text-align: right;
  flex-shrink: 0;
}

.timeline-bar-bg {
  flex-grow: 1;
  height: 8px;
  background: var(--bg-surface);
  border-radius: 4px;
  overflow: hidden;
}

.timeline-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--primary), var(--primary-light));
  border-radius: 4px;
}

.timeline-desc {
  width: 300px;
  color: var(--text-muted);
  flex-shrink: 0;
}

/* Carousel */
.carousel {
  position: relative;
  overflow: hidden;
  max-width: 800px;
  margin: 0 auto;
}

.carousel-inner {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 2rem;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.5rem;
  font-style: italic;
  margin-bottom: 1.5rem;
  color: white;
}

.testimonial-author {
  color: var(--primary-light);
  font-weight: 600;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--bg-surface);
  cursor: pointer;
  transition: background 0.3s;
}

.dot.active {
  background: var(--primary-light);
}

/* Form */
.form-container {
  background: var(--bg-card);
  padding: 3rem;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  max-width: 700px;
  margin: 0 auto;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.form-group.full-width {
  grid-column: span 2;
}

label {
  font-weight: 500;
  font-size: 0.9rem;
}

input, select, textarea {
  padding: 0.75rem 1rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: white;
  font-family: 'Inter', sans-serif;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--primary-light);
  box-shadow: 0 0 0 2px rgba(0, 180, 216, 0.2);
}

.form-error {
  color: #ef4444;
  font-size: 0.8rem;
  margin-top: 0.25rem;
  display: none;
}

input:invalid.touched + .form-error {
  display: block;
}

/* Checkmark List */
.check-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.check-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.check-icon {
  color: var(--accent-green);
  font-size: 1.5rem;
  line-height: 1;
}

/* Footer */
footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  padding: 4rem 0 2rem;
  margin-top: 4rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-col h4 {
  color: white;
  margin-bottom: 1.5rem;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-links a {
  color: var(--text-muted);
}

.footer-links a:hover {
  color: var(--primary-light);
}

.footer-bottom {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
  color: var(--text-muted);
  font-size: 0.9rem;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background: var(--bg-card);
  border-top: 1px solid var(--border-color);
  padding: 1.5rem;
  z-index: 2000;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 2rem;
  box-shadow: 0 -10px 30px rgba(0,0,0,0.5);
  transform: translateY(100%);
  transition: transform 0.5s ease;
}

.cookie-banner.show {
  transform: translateY(0);
}

.cookie-text {
  flex-grow: 1;
}

.cookie-actions {
  display: flex;
  gap: 1rem;
  flex-shrink: 0;
}

/* Responsive */
@media (max-width: 768px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .form-group.full-width { grid-column: span 1; }
  .stats-container { gap: 2rem; }
  .timeline-item { flex-direction: column; align-items: flex-start; gap: 0.5rem; }
  .timeline-desc { width: 100%; }
  .timeline-bar-bg { width: 100%; }
  .timeline-time { text-align: left; }
  .diagram { flex-direction: column; }
  .diagram-connector { width: 2px; height: 50px; min-width: 2px; }
  .cookie-banner { flex-direction: column; text-align: center; }
  .nav-links { display: none; } /* Simplified for this exercise */
}

document.addEventListener('DOMContentLoaded', () => {
  // Tabs
  const tabContainers = document.querySelectorAll('.tabs-container');
  tabContainers.forEach(container => {
    const btns = container.querySelectorAll('.tab-btn');
    const panes = container.querySelectorAll('.tab-pane');

    btns.forEach((btn, index) => {
      btn.addEventListener('click', () => {
        btns.forEach(b => b.classList.remove('active'));
        panes.forEach(p => p.classList.remove('active'));

        btn.classList.add('active');
        panes[index].classList.add('active');
      });
    });
  });

  // Accordion
  const accordionItems = document.querySelectorAll('.accordion-item');
  accordionItems.forEach(item => {
    const header = item.querySelector('.accordion-header');
    header.addEventListener('click', () => {
      const isActive = item.classList.contains('active');

      // Close all
      accordionItems.forEach(i => i.classList.remove('active'));

      // Open clicked if it wasn't active
      if (!isActive) {
        item.classList.add('active');
      }
    });
  });

  // Carousel
  const carousels = document.querySelectorAll('.carousel');
  carousels.forEach(carousel => {
    const inner = carousel.querySelector('.carousel-inner');
    const dots = carousel.querySelectorAll('.dot');
    let currentIndex = 0;

    dots.forEach((dot, index) => {
      dot.addEventListener('click', () => {
        currentIndex = index;
        updateCarousel();
      });
    });

    function updateCarousel() {
      inner.style.transform = `translateX(-${currentIndex * 100}%)`;
      dots.forEach(d => d.classList.remove('active'));
      dots[currentIndex].classList.add('active');
    }
  });

  // Form Validation
  const demoForm = document.getElementById('demo-form');
  if (demoForm) {
    const inputs = demoForm.querySelectorAll('input, select, textarea');

    inputs.forEach(input => {
      input.addEventListener('blur', () => {
        input.classList.add('touched');
      });
    });

    demoForm.addEventListener('submit', (e) => {
      e.preventDefault();
      let isValid = true;

      inputs.forEach(input => {
        input.classList.add('touched');
        if (!input.checkValidity()) {
          isValid = false;
        }
      });

      if (isValid) {
        alert('Thank you for your request. We will contact you shortly.');
        demoForm.reset();
        inputs.forEach(input => input.classList.remove('touched'));
      }
    });
  }

  // Cookie Banner
  const cookieBanner = document.getElementById('cookie-banner');
  if (cookieBanner) {
    const hasConsent = localStorage.getItem('cookieConsent');
    if (!hasConsent) {
      setTimeout(() => cookieBanner.classList.add('show'), 1000);
    }

    const acceptBtn = document.getElementById('accept-cookies');
    const declineBtn = document.getElementById('decline-cookies');

    if (acceptBtn) {
      acceptBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'accepted');
        cookieBanner.classList.remove('show');
      });
    }

    if (declineBtn) {
      declineBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'declined');
        cookieBanner.classList.remove('show');
      });
    }
  }
});
